import React from "react";
import { Link, useLocation } from 'react-router-dom';
import axios from 'axios';
//componentes
import Sidebar from "../../components/Sidebar_p-a";
import HeaderProductos from "../../components/HeaderProductos";
import "../../components/admin.css";

const API_URL_PRODUCTOS = "http://localhost:3001/api/productos";

export default function Productos(){
    const [productos, setProductos] = useState([]);
    const [cargando, setCargando] = useState(true);
    const [error, setError] = useState(null);

    const fetchProductos = async () => {
        try {
            setCargando(true);
            const response = await axios.get(API_URL_PRODUCTOS);
            // el backend devuelve un array de productos
            setProductos(response.data); 
            setError(null); // Limpiar errores previos
        } catch (err) {
            console.error("Error al cargar los productos:", err);
            setError("Error al cargar los productos. Por favor, intente de nuevo más tarde.");
        } finally {
            setCargando(false);
        }
    };

    // useEffect para llamar a la función
    useEffect(() => {
        fetchProductos();
    }, []); // array vacío 

    return(
        <div className="dashboard-layout">
        <Sidebar />

            <main className="contenido">
            <HeaderProductos /> 

                <section className="cuadro-blanco">
                    <div className="acciones">
                        
                        <button className="btn-categoria">Confecciones</button> 
                        
                    
                        <input type="text" placeholder="Filtrar categoria" className="buscar" /> 

                        <Link to="/registro_prod" className="registrar">
                            <button className="btn-registrar">
                                Registrar nuevo Producto
                            </button>
                        </Link>
                    </div>

                    
                    <table className="tabla">
                        <thead>
                            <tr>
                                <th>ID</th>
                                <th>Imagen</th>
                                <th>Producto</th>
                                <th>Categoria</th>
                                <th>Clasificación</th>
                                <th>Descripción</th>
                                <th>Precio</th>
                                <th>Stock</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        
                        <tbody>
                            {/*fila1*/}
                            <tr>
                                <td>001</td>
                                <td></td>
                                <td>Virgencitas de crochet de 20 CM</td>
                                <td>Tejidos</td>
                                <td></td>
                                <td>Hechas totalmente a mano con hilo de algodón. Tamaño 20 cm. Ideales para regalo o decoración.</td>
                                <td>$45.000</td>
                                <td>120</td>
                                <td>
                                    {/* Los enlaces de acción usan los className 'editar' y 'eliminar' */}
                                    <Link to="/editar_productos" className="editar">Editar</Link>
                                    <Link to="/productos" className="eliminar">Eliminar</Link>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </section>
            </main>
        </div> 
    );
}
